test('invoiceTotals calculation order', () => {
  // Verify: total = subtotal - discount + vat - voucher
  const invoice = {
    lines: [{ qty: 100, unitPrice: 1000, discountPercent: 10, vatRate: 21 }],
    voucher: { code: 'X', amount: 500 }
  };

  const totals = invoiceTotals(invoice);
  const calculated = totals.subtotal - totals.discount + totals.vat - totals.voucher;
  assert.equal(totals.total, calculated);
});

test('lineDiscount with bulk discount (qty >= 10)', () => {
  // 10 units × 1000 = 10000 total
  // Line discount 10%: 1000
  // Remaining: 9000
  // Bulk discount 2.5% on remaining: 225
  // Total discount: 1225
  assert.equal(lineDiscount({ qty: 10, unitPrice: 1000, discountPercent: 10, vatRate: 0 }), 1225);
});

test('lineDiscount without bulk discount (qty < 10)', () => {
  // 9 units × 1000 = 9000 total
  // Line discount 10%: 900
  // No bulk discount (qty < 10)
  // Total discount: 900
  assert.equal(lineDiscount({ qty: 9, unitPrice: 1000, discountPercent: 10, vatRate: 0 }), 900);
});

test('lineDiscount with bulk discount and no line discount', () => {
  // 10 units × 1000 = 10000 total
  // Line discount 0%: 0
  // Remaining: 10000
  // Bulk discount 2.5%: 250
  // Total discount: 250
  assert.equal(lineDiscount({ qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 0 }), 250);
});

test('lineDiscount bulk discount with large quantities', () => {
  // 100 units × 8500 = 850000 total
  // Line discount 10%: 85000
  // Remaining: 765000
  // Bulk discount 2.5%: 19125
  // Total discount: 104125
  assert.equal(lineDiscount({ qty: 100, unitPrice: 8500, discountPercent: 10, vatRate: 0 }), 104125);
});

test('lineVAT with bulk discount applied', () => {
  // 10 units × 1000 = 10000 total
  // Line discount 10%: 1000
  // Remaining: 9000
  // Bulk discount 2.5%: 225
  // VAT base: 10000 - 1225 = 8775
  // VAT at 21%: 1842.75 -> 1843
  const line = { qty: 10, unitPrice: 1000, discountPercent: 10, vatRate: 21 };
  assert.equal(lineVAT(line), 1843);
});

test('lineVAT without bulk discount', () => {
  // 9 units × 1000 = 9000 total
  // Line discount 10%: 900
  // No bulk discount
  // VAT base: 9000 - 900 = 8100
  // VAT at 21%: 1701
  const line = { qty: 9, unitPrice: 1000, discountPercent: 10, vatRate: 21 };
  assert.equal(lineVAT(line), 1701);
});

test('invoiceTotals with bulk discount', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 10, vatRate: 21 }
    ]
  };

  const totals = invoiceTotals(invoice);
  // Subtotal: 10000
  // Line discount: 1000
  // Bulk discount: 250 (2.5% of 9000)
  // Total discount: 1250
  // VAT base: 10000 - 1250 = 8750
  // VAT: 1837.5 -> 1838
  // Total: 10000 - 1250 + 1838 = 10588
  assert.equal(totals.subtotal, 10000);
  assert.equal(totals.discount, 1250);
  assert.equal(totals.vat, 1838);
  assert.equal(totals.total, 10588);
});

test('invoiceTotals with mixed quantities (some with bulk, some without)', () => {
  const invoice = {
    lines: [
      { qty: 10, unitPrice: 1000, discountPercent: 0, vatRate: 21 },
      { qty: 5, unitPrice: 1000, discountPercent: 0, vatRate: 21 }
    ]
  };

  const totals = invoiceTotals(invoice);
  // First line: 10000, line discount 0, bulk discount 250, vat base 9750, vat 2047.5 -> 2048
  // Second line: 5000, line discount 0, no bulk discount, vat base 5000, vat 1050
  // Subtotal: 15000, Discount: 250, VAT: 3098, Total: 17848
  assert.equal(totals.subtotal, 15000);
  assert.equal(totals.discount, 250);
  assert.equal(totals.vat, 3098);
  assert.equal(totals.total, 17848);
});

test('lineDiscount bulk discount with very small unit price', () => {
  // 10 units × 50 = 500 total
  // Line discount 0%: 0
  // Remaining: 500
  // Bulk discount 2.5%: 12.5 -> 12 or 13
  const line = { qty: 10, unitPrice: 50, discountPercent: 0, vatRate: 0 };
  const discount = lineDiscount(line);
  assert.ok(discount >= 12 && discount <= 13);
});

test('lineDiscount bulk discount at exactly 10 units', () => {
  // 10 units × 100 = 1000
  // Line discount 5%: 50
  // Remaining: 950
  // Bulk discount 2.5%: 23.75 -> 24
  // Total: 74
  const line = { qty: 10, unitPrice: 100, discountPercent: 5, vatRate: 0 };
  assert.equal(lineDiscount(line), 74);
});

test('lineDiscount no bulk discount at 9 units', () => {
  // 9 units × 100 = 900
  // Line discount 5%: 45
  // No bulk discount
  // Total: 45
  const line = { qty: 9, unitPrice: 100, discountPercent: 5, vatRate: 0 };
  assert.equal(lineDiscount(line), 45);
});

test('invoiceTotals with bulk discount and line discount combined', () => {
  const invoice = {
    lines: [
      { qty: 20, unitPrice: 5000, discountPercent: 15, vatRate: 21 }
    ]
  };

  const totals = invoiceTotals(invoice);
  // Subtotal: 100000
  // Line discount 15%: 15000
  // Remaining: 85000
  // Bulk discount 2.5%: 2125
  // Total discount: 17125
  // VAT base: 100000 - 17125 = 82875
  // VAT: 17403.75 -> 17404
  // Total: 100000 - 17125 + 17404 = 100279
  assert.equal(totals.subtotal, 100000);
  assert.equal(totals.discount, 17125);
  assert.equal(totals.vat, 17404);
  assert.equal(totals.total, 100279);
});

