1	import { ok, fail } from './result.js';
2	
3	/**
4	 * Exchange rates: units of that currency per euro.
5	 */
6	export const RATES = {
7	  EUR: 1,
8	  USD: 1.085,
9	  GBP: 0.8425
10	};
11	
12	/**
13	 * Round a (possibly fractional) number of cents to a whole cent, half to even (banker's rounding):
14	 * 124.5 -> 124, 125.5 -> 126, 2.4 -> 2, -0.5 -> 0.
15	 * @param {number} x
16	 * @returns {number}
17	 */
18	export function roundCents(x) {
19	  const r = Math.round(x * 1e6) / 1e6; // drop binary noise such as 124.49999999999999
20	  const floor = Math.floor(r);
21	  const diff = r - floor;
22	  if (diff > 0.5) return floor + 1;
23	  if (diff < 0.5) return floor === 0 ? 0 : floor;
24	  return floor % 2 === 0 ? floor : floor + 1;
25	}
26	
27	/**
28	 * Format cents as euros for people: 123456 -> "€1,234.56", -5 -> "-€0.05".
29	 * @param {number} cents
30	 * @returns {string}
31	 */
32	export function formatEuros(cents) {
33	  const sign = cents < 0 ? '-' : '';
34	  const abs = Math.abs(cents);
35	  const euros = Math.floor(abs / 100).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',');
36	  return `${sign}€${euros}.${String(abs % 100).padStart(2, '0')}`;
37	}
38	
39	/**
40	 * Parse a euro amount typed by a person ("12", "12.5", "1,234.56") into cents.
41	 * @param {string} text
42	 * @returns {{ ok: true, value: number } | { ok: false, error: string }}
43	 */
44	export function parseEuros(text) {
45	  const m = /^(\d{1,3}(?:,\d{3})*|\d+)(?:\.(\d{1,2}))?$/.exec(String(text).trim());
46	  if (!m) return fail('AMOUNT_INVALID');
47	  const euros = Number(m[1].replace(/,/g, ''));
48	  const cents = Number((m[2] ?? '').padEnd(2, '0'));
49	  return ok(euros * 100 + cents);
50	}
51	
52	/**
53	 * Convert an amount from euros to another currency.
54	 * @param {number} cents amount in euro cents
55	 * @param {string} currency target currency (EUR, USD, GBP)
56	 * @returns {{ ok: true, value: number } | { ok: false, error: string }}
57	 */
58	export function convert(cents, currency) {
59	  if (!RATES[currency]) {
60	    return fail('UNKNOWN_CURRENCY');
61	  }
62	  const amountInTargetCurrency = cents * RATES[currency];
63	  return ok(Math.round(amountInTargetCurrency));
64	}
65	
66	/**
67	 * Format an amount in a specific currency, with currency sign.
68	 * @param {number} cents amount in that currency's cents
69	 * @param {string} currency (EUR, USD, GBP)
70	 * @returns {string}
71	 */
72	export function formatMoney(cents, currency) {
73	  if (!RATES[currency]) {
74	    return 'unknown currency';
75	  }
76	
77	  const sign = cents < 0 ? '-' : '';
78	  const abs = Math.abs(cents);
79	  const euros = Math.floor(abs / 100).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',');
80	  const remainder = String(abs % 100).padStart(2, '0');
81	
82	  const currencySymbols = {
83	    EUR: '€',
84	    USD: '$',
85	    GBP: '£'
86	  };
87	
88	  return `${sign}${currencySymbols[currency]}${euros}.${remainder}`;
89	}
