1	import { ok, fail } from './result.js';
2	import { getCustomer, TIER_DISCOUNTS, normalizeId } from './customers.js';
3	import { getProduct } from './catalogue.js';
4	import { nextInvoiceNumber } from './numbering.js';
5	import { isValidDate, addDays, getLastDayOfMonth } from './dates.js';
6	import { lineTotal, lineDiscount, lineVAT, invoiceTotals } from './totals.js';
7	
8	// Re-export totals functions for backwards compatibility
9	export { lineTotal, lineDiscount, lineVAT, invoiceTotals };
10	
11	/**
12	 * Create a new draft invoice.
13	 * @param {{ customerId: string, issueDate: string, lines: Array<{ sku: string, qty: number }>, terms?: string }}
14	 * @returns {{ ok: true, value: { customerId: string, issueDate: string, status: string, lines: Array, terms: string, dueDate: string } } | { ok: false, error: string }}
15	 */
16	export function createInvoice({ customerId, issueDate, lines, terms }) {
17	  // Normalize customer ID
18	  const normalizedCustomerId = normalizeId(customerId);
19	
20	  // Validate customer exists
21	  const customerResult = getCustomer(normalizedCustomerId);
22	  if (!customerResult.ok) return customerResult;
23	
24	  // Validate issueDate is in YYYY-MM-DD format
25	  if (!isValidDate(issueDate)) return fail('DATE_INVALID');
26	
27	  // Validate and set default terms
28	  const finalTerms = terms ?? 'NET30';
29	  if (!['NET14', 'NET30', 'EOM'].includes(finalTerms)) {
30	    return fail('TERMS_INVALID');
31	  }
32	
33	  // Calculate due date based on terms
34	  let dueDate;
35	  if (finalTerms === 'NET14') {
36	    dueDate = addDays(issueDate, 14);
37	  } else if (finalTerms === 'NET30') {
38	    dueDate = addDays(issueDate, 30);
39	  } else if (finalTerms === 'EOM') {
40	    dueDate = getLastDayOfMonth(issueDate);
41	  }
42	
43	  // Validate lines is not empty
44	  if (!Array.isArray(lines) || lines.length === 0) return fail('NO_LINES');
45	
46	  // Process lines and validate each
47	  const processedLines = [];
48	  for (const line of lines) {
49	    // Validate qty is a positive integer
50	    if (!Number.isInteger(line.qty) || line.qty <= 0) return fail('QTY_INVALID');
51	
52	    // Determine discountPercent: use explicit value if provided, otherwise use tier discount
53	    let discountPercent;
54	    if (line.hasOwnProperty('discountPercent')) {
55	      // Explicit value provided (even if 0)
56	      discountPercent = line.discountPercent;
57	      if (typeof discountPercent !== 'number' || discountPercent < 0 || discountPercent > 100) {
58	        return fail('DISCOUNT_INVALID');
59	      }
60	    } else {
61	      // No explicit value, use customer tier discount
62	      discountPercent = TIER_DISCOUNTS[customerResult.value.tier];
63	    }
64	
65	    // Get product
66	    const productResult = getProduct(line.sku);
67	    if (!productResult.ok) return productResult;
68	
69	    const product = productResult.value;
70	    processedLines.push({
71	      sku: line.sku,
72	      name: product.name,
73	      qty: line.qty,
74	      unitPrice: product.unitPrice,
75	      vatRate: product.vatRate,
76	      discountPercent
77	    });
78	  }
79	
80	  return ok({
81	    customerId: normalizedCustomerId,
82	    issueDate,
83	    status: 'draft',
84	    terms: finalTerms,
85	    dueDate,
86	    lines: processedLines
87	  });
88	}
