108	    if (typeof finalDiscount !== 'number' || finalDiscount < 0 || finalDiscount > 100) {
109	      return fail('DISCOUNT_INVALID');
110	    }
111	  } else {
112	    // No explicit value, use customer tier discount
113	    const customerResult = getCustomer(normalizeId(invoice.customerId));
114	    if (!customerResult.ok) return customerResult;
115	    finalDiscount = TIER_DISCOUNTS[customerResult.value.tier];
116	  }
117	
118	  // Get product and validate SKU exists
119	  const productResult = getProduct(sku);
120	  if (!productResult.ok) return productResult;
121	
122	  const product = productResult.value;
123	  const newLines = invoice.lines.map((line) => ({ ...line }));
124	
125	  // Check if SKU already exists
126	  const existingIndex = newLines.findIndex((line) => line.sku === sku);
127	
128	  if (existingIndex !== -1) {
129	    // Increase qty on existing line
130	    newLines[existingIndex].qty += qty;
131	  } else {
132	    // Add new line at the end
133	    newLines.push({
134	      sku,
135	      name: product.name,
136	      qty,
137	      unitPrice: product.unitPrice,
138	      vatRate: product.vatRate,
139	      discountPercent: finalDiscount
140	    });
141	  }
142	
143	  return ok({
144	    ...invoice,
145	    lines: newLines
146	  });
