12	/**
13	 * Calculate the discount amount for a line item (lineTotal × discountPercent / 100 + bulk discount if qty >= 10, clamped at 0).
14	 * Bulk discount of 2.5% is applied after the line discount to the remaining amount.
15	 * @param {{ qty: number, unitPrice: number, discountPercent?: number }}
