17	 */
18	export function lineDiscount(line) {
19	  const discountPercent = line.discountPercent ?? 0;
20	  const total = lineTotal(line);
21	  const lineDiscountAmount = roundCents(total * discountPercent / 100);
22	
23	  // Apply bulk discount (2.5%) to what remains after line discount
24	  let totalDiscount = lineDiscountAmount;
25	  if (line.qty >= 10) {
26	    const remainingAfterLineDiscount = total - lineDiscountAmount;
27	    const bulkDiscountAmount = roundCents(remainingAfterLineDiscount * 2.5 / 100);
28	    totalDiscount = lineDiscountAmount + bulkDiscountAmount;
29	  }
30	
31	  return Math.max(0, totalDiscount);
32	}
