36	 * @param {{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }}
37	 * @returns {number}
38	 */
39	export function lineVAT(line) {
40	  const amountAfterDiscount = lineTotal(line) - lineDiscount(line);
41	  const vat = roundCents(amountAfterDiscount * line.vatRate / 100);
42	  return Math.max(0, vat);
43	}
