46	 * Calculate totals for an invoice.
47	 * @param {{ lines: Array<{ qty: number, unitPrice: number, discountPercent?: number, vatRate: number }>, voucher?: { amount: number } }}
48	 * @returns {{ subtotal: number, discount: number, vat: number, voucher: number, total: number }}
49	 */
50	export function invoiceTotals(invoice) {
51	  const subtotal = invoice.lines.reduce((sum, line) => sum + lineTotal(line), 0);
52	  const discount = invoice.lines.reduce((sum, line) => sum + lineDiscount(line), 0);
53	  const vat = invoice.lines.reduce((sum, line) => sum + lineVAT(line), 0);
54	  const voucher = invoice.voucher?.amount ?? 0;
55	  const total = Math.max(0, subtotal - discount + vat - voucher);
56	  return { subtotal, discount, vat, voucher, total };
